"use client";

import { useState, useEffect } from "react";
import { useSubmit } from "@/components/finance/FormModal";
import { Empty } from "@/components/finance/Skeleton";
import { useFinanceData } from "@/lib/api";
import { Holdings, Quality, Research } from "@/lib/types";

const InvestmentsPage = () => {
  const [data, setData] = useState<Holdings | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const submit = useSubmit();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await useFinanceData("/finance/investments");
        setData(response.data);
      } catch (err) {
        setError(err as Error);
      }
    };

    fetchData();
  }, []);

  if (!data) return <Empty />;

  return (
    <div>
      <h1>Investments</h1>
      <table>
        <thead>
          <tr>
            <th>Asset</th>
            <th>Units</th>
            <th>Price</th>
            <th>Edit</th>
            <th>Archive</th>
            <th>Delete</th>
          </tr>
        </thead>
        <tbody>
          {data.holdings.map((holding) => (
            <tr key={holding.id}>
              <td>{holding.asset}</td>
              <td>{holding.units}</td>
              <td>{holding.price}</td>
              <td>
                <button onClick={() => submit(`/finance/investments/${holding.id}`, { method: "PUT" })}>Edit</button>
              </td>
              <td>
                <button onClick={() => submit(`/finance/investments/${holding.id}/archive`, { method: "PUT" })}>Archive</button>
              </td>
              <td>
                {holding.lots_count === 0 && (
                  <button onClick={() => submit(`/finance/investments/${holding.id}`, { method: "DELETE" })}>Delete</button>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <Quality data={data.quality} />
      <Research data={data.research} />
      {/* Visuals components go here */}
    </div>
  );
};

export default InvestmentsPage;
